from collections import Counter, defaultdict

def infer_transform(grid):
    h,w=len(grid),len(grid[0])
    axes={
        'row': lambda r,c:r,
        'col': lambda r,c:c,
        'diff':lambda r,c:c-r,
        'sum':lambda r,c:r+c,
    }
    pts=[(r,c,v) for r in range(h) for c in range(w) if (v:=grid[r][c])!=0]
    # Select stripe direction where same-color marks are most concentrated into long lines.
    scores={}
    for name,fn in axes.items():
        counts=Counter((fn(r,c),v) for r,c,v in pts)
        scores[name]=sum(n*n for n in counts.values())
    axis=max(axes,key=lambda a:scores[a])
    fn=axes[axis]
    vals=[(fn(r,c),v) for r,c,v in pts]
    # Find shortest periodic coloring of the marked stripe coordinates.
    p=None; mapping=None
    for q in range(1, max(h,w)*2+1):
        m={}; ok=True
        for k,v in vals:
            z=k%q
            if z in m and m[z]!=v:
                ok=False; break
            m[z]=v
        if ok:
            p=q; mapping=m; break
    if p is None: raise ValueError('no period')
    # If marked residues do not cover all positions, default to nearest residue class color.
    keys=list(mapping)
    def col(k):
        z=k%p
        if z in mapping:return mapping[z]
        nearest=min(keys,key=lambda x:min((z-x)%p,(x-z)%p))
        return mapping[nearest]
    return [[col(fn(r,c)) for c in range(w)] for r in range(h)], (axis,p,mapping,scores)

